# Adaptive rejection sampler (Gilks and Wild, 1992)
# The supplied density is an (unnormalised) vectorised density, not a log density.

sample_count <- 100L

.ars_call_density <- function(f, x) {
  ans <- tryCatch({
    if (is.function(f)) f(x)
    else if (is.expression(f)) eval(f[[1L]], envir = list(x = x))
    else if (is.character(f) && length(f) == 1L) eval(parse(text = f), envir = list(x = x))
    else stop("density_function must be a function, expression, or expression string")
  }, error = function(e) stop("could not evaluate density_function: ", conditionMessage(e)))
  if (length(ans) == 1L && length(x) > 1L) ans <- rep(ans, length(x))
  if (length(ans) != length(x) || !is.numeric(ans))
    stop("density_function must return one numeric value per input x")
  ans
}

.ars_log_density <- function(f, x) {
  d <- .ars_call_density(f, x)
  if (any(is.na(d)) || any(d < 0) || any(is.nan(d)))
    stop("density_function returned NA, NaN, or a negative value")
  out <- rep(-Inf, length(d))
  pos <- d > 0
  out[pos] <- log(d[pos])
  if (any(is.infinite(d) & d > 0)) stop("density_function returned positive infinity")
  out
}

.ars_check_concavity <- function(x, y, tolerance = 2e-4) {
  keep <- is.finite(y)
  x <- x[keep]; y <- y[keep]
  if (length(x) < 3L) return(TRUE)
  o <- order(x); x <- x[o]; y <- y[o]
  slopes <- diff(y) / diff(x)
  if (any(!is.finite(slopes))) return(FALSE)
  # Secant slopes of a concave function are non-increasing.
  all(diff(slopes) <= tolerance * (1 + max(abs(slopes))))
}

.ars_initial_points <- function(domain) {
  lo <- domain[1L]; hi <- domain[2L]
  if (is.finite(lo) && is.finite(hi)) seq(lo, hi, length.out = 7L)[-c(1L, 7L)]
  else if (!is.finite(lo) && !is.finite(hi)) c(-2, -1, 0, 1, 2)
  else if (is.finite(lo)) lo + c(.25, .75, 1.5, 3, 6, 12)
  else hi - c(.25, .75, 1.5, 3, 6, 12)
}

.ars_derivatives <- function(x, y, f, domain) {
  lo <- domain[1L]; hi <- domain[2L]
  h <- pmax(1e-5, 1e-4 * pmax(1, abs(x)))
  if (is.finite(lo)) h <- pmin(h, (x - lo) / 3)
  if (is.finite(hi)) h <- pmin(h, (hi - x) / 3)
  h <- pmax(h, 1e-8)
  yl <- .ars_log_density(f, x - h)
  yr <- .ars_log_density(f, x + h)
  s <- (yr - yl) / (2 * h)
  # One-sided differences are needed if a very short bounded interval is used.
  bad <- !is.finite(s)
  if (any(bad)) {
    s[bad] <- (y[bad] - yl[bad]) / h[bad]
    s[bad & !is.finite(s)] <- (yr[bad & !is.finite(s)] - y[bad & !is.finite(s)]) / h[bad & !is.finite(s)]
  }
  if (any(!is.finite(s))) stop("unable to calculate finite log-density slopes")
  s
}

.ars_hull <- function(x, y, slope, domain) {
  o <- order(x); x <- x[o]; y <- y[o]; slope <- slope[o]
  n <- length(x)
  z <- rep(NA_real_, n + 1L); z[1L] <- domain[1L]; z[n + 1L] <- domain[2L]
  if (n > 1L) {
    z[2:n] <- (y[-n] - slope[-n] * x[-n] - y[-1L] + slope[-1L] * x[-1L]) /
      (slope[-1L] - slope[-n])
  }
  if (any(!is.na(z[2:n]) & (z[2:n] <= x[-n] | z[2:n] >= x[-1L])))
    stop("log-concavity check failed: tangent intersections are not ordered")
  if (any(diff(z) <= 0)) stop("log-concavity check failed: invalid hull intervals")
  intercept <- y - slope * x
  logmass <- numeric(n)
  for (i in seq_len(n)) {
    a <- z[i]; b <- z[i + 1L]; m <- slope[i]; c <- intercept[i]
    if (abs(m) < 1e-10) {
      if (!is.finite(b - a)) stop("the proposed envelope has infinite mass")
      logmass[i] <- c + log(b - a)
    } else {
      # Both terms below are non-positive in a well behaved tail, preventing overflow.
      q <- max(m * a, m * b)
      if (!is.finite(q)) q <- 0
      v <- exp(m * a - q) - exp(m * b - q)
      if (v <= 0 || !is.finite(v)) stop("invalid exponential envelope; check log-concavity and tails")
      logmass[i] <- c + q + log(abs(v / m))
    }
  }
  list(x=x, y=y, slope=slope, intercept=intercept, z=z, logmass=logmass)
}

.ars_draw_envelope <- function(hull) {
  w <- exp(hull$logmass - max(hull$logmass))
  i <- sample.int(length(w), 1L, prob = w)
  a <- hull$z[i]; b <- hull$z[i + 1L]; m <- hull$slope[i]
  u <- runif(1L)
  if (abs(m) < 1e-10) a + u * (b - a)
  else log(exp(m * a) + u * (exp(m * b) - exp(m * a))) / m
}

#' Draw n observations using adaptive rejection sampling.
ars <- function(density_function, domain, n = sample_count) {
  if (!is.function(density_function) && !is.expression(density_function) &&
      !(is.character(density_function) && length(density_function) == 1L))
    stop("density_function must be a function or expression")
  if (!is.numeric(domain) || length(domain) != 2L || any(is.na(domain)) ||
      domain[1L] >= domain[2L] || domain[1L] == Inf || domain[2L] == -Inf)
    stop("domain must be c(lower, upper), with lower < upper")
  if (!is.numeric(n) || length(n) != 1L || is.na(n) || !is.finite(n) || n < 0 || n != as.integer(n))
    stop("n must be one non-negative integer")
  n <- as.integer(n)
  if (n == 0L) return(numeric(0L))

  knots <- .ars_initial_points(domain)
  knots <- knots[knots > domain[1L] & knots < domain[2L]]
  y <- .ars_log_density(density_function, knots)
  if (sum(is.finite(y)) < 3L) stop("density is not positive at enough interior points")
  if (!.ars_check_concavity(knots, y)) stop("density does not appear log-concave on initial points")
  slope <- .ars_derivatives(knots, y, density_function, domain)
  if (!.ars_check_concavity(knots, y)) stop("density failed the log-concavity check")
  if (is.finite(domain[1L]) && slope[1L] <= 0) stop("left tail is not compatible with a finite envelope")
  if (is.infinite(domain[1L]) && slope[1L] <= 0) stop("left tail slope must be positive")
  if (is.infinite(domain[2L]) && slope[length(slope)] >= 0) stop("right tail slope must be negative")
  hull <- .ars_hull(knots, y, slope, domain)
  out <- numeric(n); accepted <- 0L; iterations <- 0L
  while (accepted < n) {
    iterations <- iterations + 1L
    if (iterations > 200000L) stop("sampling stalled; density may not be log-concave")
    x <- .ars_draw_envelope(hull)
    yu <- hull$intercept[findInterval(x, hull$z, all.inside = TRUE)] +
      hull$slope[findInterval(x, hull$z, all.inside = TRUE)] * x
    yt <- .ars_log_density(density_function, x)
    if (is.finite(yt) && yt > yu + 1e-7) stop("non-log-concave density detected during sampling")
    if (is.finite(yt) && log(runif(1L)) <= yt - yu) { accepted <- accepted + 1L; out[accepted] <- x }
    if (is.finite(yt)) {
      knots <- sort(unique(c(knots, x))); y <- .ars_log_density(density_function, knots)
      if (!.ars_check_concavity(knots, y)) stop("non-log-concave density detected during sampling")
      slope <- .ars_derivatives(knots, y, density_function, domain)
      if (any(diff(slope) > 2e-3 * (1 + max(abs(slope))))) stop("non-log-concave density detected during sampling")
      hull <- .ars_hull(knots, y, slope, domain)
    }
  }
  out
}

# Formal stochastic tests; also writes a reproducible example sample file.
test <- function() {
  set.seed(202405)
  z <- ars(function(x) dnorm(x), c(-Inf, Inf), 5000L)
  n_ok <- abs(mean(z)) < .06 && abs(sd(z) - 1) < .06
  write.table(z, "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)
  cat(sprintf("NORMAL: %s (mean=%.4f, sd=%.4f; target mean=0, sd=1)\n", ifelse(n_ok, "PASS", "FAIL"), mean(z), sd(z)))
  e <- ars(function(x) dexp(x), c(0, Inf), 5000L)
  e_ok <- abs(mean(e) - 1) < .06 && abs(sd(e) - 1) < .06
  cat(sprintf("EXPONENTIAL: %s (mean=%.4f, sd=%.4f; target mean=1, sd=1)\n", ifelse(e_ok, "PASS", "FAIL"), mean(e), sd(e)))
  invalid_ok <- inherits(try(ars(function(x) dnorm(x), c(1, 1), 1), silent = TRUE), "try-error")
  nonconcave_ok <- inherits(try(ars(function(x) exp(-(x^2 - 1)^2), c(-Inf, Inf), 10), silent = TRUE), "try-error")
  cat(sprintf("INPUT_VALIDATION: %s (invalid domain rejected)\n", ifelse(invalid_ok, "PASS", "FAIL")))
  cat(sprintf("NON_LOG_CONCAVE_REJECTION: %s (non-log-concave density rejected)\n", ifelse(nonconcave_ok, "PASS", "FAIL")))
  invisible(all(n_ok, e_ok, invalid_ok, nonconcave_ok))
}

